-- Live guard bodies (from reviewed S3L pin). Compare to the live md5 pins (informational fixture-fidelity).
SELECT 'FIDELITY terminal_guard_md5_matches_live_pin='||(md5(pg_get_functiondef('costing.fn_enforce_mutable_refresh_run_snapshot()'::regprocedure))='2fc573625296de9ccde5d722fdd4a3de')
    ||' designated_guard='||(md5(pg_get_functiondef('costing.fn_guard_designated_run_rows()'::regprocedure))='5629ce76254a5ed45cde5529ce91caee');
SELECT set_config('costing_retention.terminal_guard_md5',md5(pg_get_functiondef('costing.fn_enforce_mutable_refresh_run_snapshot()'::regprocedure)),false);
-- Topology (names mirror live large relations). Parent/child + keyless + cache.
CREATE TABLE costing.marketing_signed_billed_sales_evidence_snapshot(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,refresh_run_id bigint NOT NULL REFERENCES costing.costing_refresh_run(id),marker text);
CREATE TABLE costing.cost_sheet_line_traceability_snapshot(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,refresh_run_id bigint NOT NULL REFERENCES costing.costing_refresh_run(id),parent_evidence_id bigint REFERENCES costing.marketing_signed_billed_sales_evidence_snapshot(id));
CREATE TABLE costing.cost_sheet_line_monthly_snapshot(refresh_run_id bigint NOT NULL REFERENCES costing.costing_refresh_run(id),line text);   -- keyless
CREATE TABLE costing.sku_scheme_viability_snapshot(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,refresh_run_id bigint NOT NULL REFERENCES costing.costing_refresh_run(id));
CREATE INDEX ON costing.marketing_signed_billed_sales_evidence_snapshot(refresh_run_id);
CREATE INDEX ON costing.cost_sheet_line_traceability_snapshot(refresh_run_id);
CREATE INDEX ON costing.cost_sheet_line_traceability_snapshot(parent_evidence_id);
CREATE INDEX ON costing.cost_sheet_line_monthly_snapshot(refresh_run_id);
CREATE INDEX ON costing.sku_scheme_viability_snapshot(refresh_run_id);
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['marketing_signed_billed_sales_evidence_snapshot','cost_sheet_line_traceability_snapshot','cost_sheet_line_monthly_snapshot','sku_scheme_viability_snapshot',
   'sku_sales_allocation_basis_snapshot','sku_regional_marketing_allocation_basis_snapshot','sku_regional_marketing_expense_allocation_snapshot'] LOOP
  EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON costing.%I(refresh_run_id)','ix_run_'||t,t);
  EXECUTE format('CREATE TRIGGER trg_designated BEFORE INSERT OR DELETE OR UPDATE ON costing.%I FOR EACH ROW EXECUTE FUNCTION costing.fn_guard_designated_run_rows()',t);
  EXECUTE format('CREATE TRIGGER trg_terminal BEFORE INSERT OR DELETE OR UPDATE ON costing.%I FOR EACH ROW EXECUTE FUNCTION costing.fn_enforce_mutable_refresh_run_snapshot()',t);
 END LOOP;
END $$;
-- data for runs: guards forbid inserting into designated/terminal runs, so load through a privileged fixture window
ALTER TABLE costing.marketing_signed_billed_sales_evidence_snapshot DISABLE TRIGGER USER; ALTER TABLE costing.cost_sheet_line_traceability_snapshot DISABLE TRIGGER USER;
ALTER TABLE costing.cost_sheet_line_monthly_snapshot DISABLE TRIGGER USER; ALTER TABLE costing.sku_scheme_viability_snapshot DISABLE TRIGGER USER;
INSERT INTO costing.marketing_signed_billed_sales_evidence_snapshot(refresh_run_id,marker) SELECT r,'m'||g FROM unnest(ARRAY[87,148,149,122,143,152,153]) r,generate_series(1,5) g;
INSERT INTO costing.cost_sheet_line_traceability_snapshot(refresh_run_id,parent_evidence_id) SELECT e.refresh_run_id,e.id FROM costing.marketing_signed_billed_sales_evidence_snapshot e;
INSERT INTO costing.cost_sheet_line_monthly_snapshot SELECT refresh_run_id,'l'||id FROM costing.marketing_signed_billed_sales_evidence_snapshot;
INSERT INTO costing.sku_scheme_viability_snapshot(refresh_run_id) SELECT refresh_run_id FROM costing.marketing_signed_billed_sales_evidence_snapshot;
ALTER TABLE costing.marketing_signed_billed_sales_evidence_snapshot ENABLE TRIGGER USER; ALTER TABLE costing.cost_sheet_line_traceability_snapshot ENABLE TRIGGER USER;
ALTER TABLE costing.cost_sheet_line_monthly_snapshot ENABLE TRIGGER USER; ALTER TABLE costing.sku_scheme_viability_snapshot ENABLE TRIGGER USER;
-- run 87's regional/sales snapshot rows were created in 01_seed (guards now apply to later writes only)
CREATE TABLE t.base AS SELECT 'x'::text k;   -- placeholder
\i ../candidates/R4_guarded_purge.sql
-- 1. structural blockers before any review: everything unclassified
SELECT t.mark('r4a');
DO $$ BEGIN
 ASSERT (SELECT count(*) FROM costing_retention.fn_purge_structural_blockers() WHERE blocker='UNCLASSIFIED_RUN_LINKED_RELATION')>=10,'unreviewed topology is blocked';
 PERFORM t.fails('SELECT costing_retention.purge_run_step(87)','PURGE_BLOCKED.*(UNCLASSIFIED|DISPLAYED|DESIGNATION|CURRENT)');
END $$;
-- 2. reviewed allowlist (explicit; never derived from names)
INSERT INTO costing_retention.purge_allowlist(table_schema,table_name,run_column,classification,reviewed_by,note) VALUES
 ('costing','marketing_signed_billed_sales_evidence_snapshot','refresh_run_id','SNAPSHOT_PURGEABLE','fixture','large evidence snapshot'),
 ('costing','cost_sheet_line_traceability_snapshot','refresh_run_id','SNAPSHOT_PURGEABLE','fixture','child of signed evidence'),
 ('costing','cost_sheet_line_monthly_snapshot','refresh_run_id','SNAPSHOT_PURGEABLE','fixture','keyless snapshot'),
 ('costing','sku_scheme_viability_snapshot','refresh_run_id','CACHE_PURGEABLE','fixture','scheme comparison cache'),
 ('costing','sku_sales_allocation_basis_snapshot','refresh_run_id','SNAPSHOT_PURGEABLE','fixture',NULL),
 ('costing','sku_regional_marketing_allocation_basis_snapshot','refresh_run_id','SNAPSHOT_PURGEABLE','fixture',NULL),
 ('costing','sku_regional_marketing_expense_allocation_snapshot','refresh_run_id','SNAPSHOT_PURGEABLE','fixture',NULL),
 ('costing','costing_run_designation','refresh_run_id','PERMANENT','fixture','governance'),
 ('costing','regional_marketing_evidence_acceptance','source_refresh_run_id','PERMANENT','fixture','governance'),
 ('costing','sales_allocation_quantity_driver_acceptance','source_refresh_run_id','PERMANENT','fixture','governance'),
 ('costing','governance_evidence_event','source_refresh_run_id','PERMANENT','fixture','governance'),
 ('costing','costing_run_retention_ledger','refresh_run_id','PERMANENT','fixture','ledger'),
 ('costing_retention','purge_step_receipt','refresh_run_id','PERMANENT','fixture','receipts');
DO $$ DECLARE n int; BEGIN
 SELECT count(*) INTO n FROM costing_retention.fn_purge_structural_blockers();
 ASSERT n=0,'reviewed topology has no structural blockers, got '||n||': '||(SELECT string_agg(blocker||' '||detail,'; ') FROM costing_retention.fn_purge_structural_blockers());
 ASSERT (SELECT array_agg(table_name ORDER BY ord) FROM costing_retention.fn_purge_order() WHERE table_name IN ('marketing_signed_billed_sales_evidence_snapshot','cost_sheet_line_traceability_snapshot')) = ARRAY['cost_sheet_line_traceability_snapshot','marketing_signed_billed_sales_evidence_snapshot'],'child-first order';
 ASSERT (SELECT array_agg(table_name ORDER BY ord) FROM costing_retention.fn_purge_order() WHERE table_name LIKE 'sku_regional%')=ARRAY['sku_regional_marketing_expense_allocation_snapshot','sku_regional_marketing_allocation_basis_snapshot'],'nested regional order';
END $$;
-- 3. per-run blockers: protected populations
DO $$ DECLARE b text; BEGIN
 FOREACH b IN ARRAY ARRAY['122:DESIGNATION_HISTORY','143:DESIGNATION_HISTORY','153:DISPLAYED_OR_APPROVED_POINTER|CURRENT_OR_FUTURE','152:CURRENT_OR_FUTURE_MONTH_PROTECTED','154:RUN_NOT_TERMINAL|CURRENT_OR_FUTURE'] LOOP
  ASSERT EXISTS (SELECT 1 FROM costing_retention.fn_purge_run_blockers(split_part(b,':',1)::bigint) WHERE blocker ~ split_part(b,':',2)),'expected blocker for run '||b;
  PERFORM t.fails(format('SELECT costing_retention.purge_run_step(%s)',split_part(b,':',1)),'PURGE_BLOCKED');
 END LOOP;
 ASSERT NOT EXISTS (SELECT 1 FROM costing_retention.fn_purge_run_blockers(87)),'run 87 (undesignated September draft, month closed) is eligible: '||coalesce((SELECT string_agg(blocker,',') FROM costing_retention.fn_purge_run_blockers(87)),'');
 ASSERT NOT EXISTS (SELECT 1 FROM costing_retention.fn_purge_run_blockers(148)),'run 148 October draft eligible by technical rules';
END $$;
-- 4. preview (read only) and authority model
DO $$ DECLARE n int; BEGIN
 SELECT count(*) INTO n FROM costing_retention.fn_purge_run_preview(87);
 ASSERT n=7,'preview covers all 7 purgeable relations, got '||n;
 ASSERT (SELECT rows_for_run FROM costing_retention.fn_purge_run_preview(87) WHERE table_name='marketing_signed_billed_sales_evidence_snapshot')=5,'exact indexed count';
END $$;
SET ROLE authenticated;
DO $$ BEGIN PERFORM t.fails('SELECT costing_retention.purge_run_step(87)','permission denied');
            PERFORM t.fails('SELECT * FROM costing_retention.fn_purge_run_preview(87)','permission denied');
            PERFORM t.fails($q$INSERT INTO costing_retention.purge_context VALUES(pg_backend_pid(),pg_current_xact_id(),87,'sku_scheme_viability_snapshot')$q$,'permission denied'); END $$;
RESET ROLE;
SET ROLE service_role;
DO $$ BEGIN PERFORM t.fails('SELECT costing_retention.purge_run_step(87)','permission denied'); END $$;
RESET ROLE;
SET ROLE anon;
DO $$ BEGIN PERFORM t.fails('SELECT costing_retention.purge_run_step(87)','permission denied|does not exist'); END $$;
RESET ROLE;
DO $$ BEGIN
 -- direct deletes are still refused by the ORIGINAL guards (no context)
 PERFORM t.fails('DELETE FROM costing.sku_scheme_viability_snapshot WHERE refresh_run_id=87','terminal refresh run');
 PERFORM t.fails('DELETE FROM costing.marketing_signed_billed_sales_evidence_snapshot WHERE refresh_run_id=148','terminal refresh run');
 PERFORM t.fails('UPDATE costing.sku_scheme_viability_snapshot SET refresh_run_id=refresh_run_id WHERE refresh_run_id=87','terminal refresh run');
 PERFORM t.fails('INSERT INTO costing.sku_scheme_viability_snapshot(refresh_run_id) VALUES(87)','terminal refresh run');
 -- a context for a different run / table / transaction does not authorise
 PERFORM t.fails($q$INSERT INTO costing_retention.purge_context VALUES(pg_backend_pid(),pg_current_xact_id(),148,'sku_scheme_viability_snapshot'); DELETE FROM costing.sku_scheme_viability_snapshot WHERE refresh_run_id=87$q$,'terminal refresh run');
 PERFORM t.fails($q$INSERT INTO costing_retention.purge_context VALUES(pg_backend_pid(),pg_current_xact_id(),87,'cost_sheet_line_monthly_snapshot'); DELETE FROM costing.sku_scheme_viability_snapshot WHERE refresh_run_id=87$q$,'terminal refresh run');
 -- even a forged context cannot delete a designated run: the designated-run guard is untouched
 PERFORM t.fails($q$INSERT INTO costing_retention.purge_context VALUES(pg_backend_pid(),pg_current_xact_id(),122,'sku_scheme_viability_snapshot'); DELETE FROM costing.sku_scheme_viability_snapshot WHERE refresh_run_id=122$q$,'AU2_DESIGNATED_RUN_IMMUTABLE');
 -- the session GUC style bypass used by naive designs does nothing
 PERFORM t.fails($q$SET LOCAL costing_retention.purge_authority='on'; DELETE FROM costing.sku_scheme_viability_snapshot WHERE refresh_run_id=87$q$,'terminal refresh run');
END $$;
-- 5. cross-run reference (planted in a fixture-only window) blocks the run that owns the parent
ALTER TABLE costing.cost_sheet_line_traceability_snapshot DISABLE TRIGGER USER;
INSERT INTO costing.cost_sheet_line_traceability_snapshot(refresh_run_id,parent_evidence_id) SELECT 148,min(id) FROM costing.marketing_signed_billed_sales_evidence_snapshot WHERE refresh_run_id=87;
ALTER TABLE costing.cost_sheet_line_traceability_snapshot ENABLE TRIGGER USER;
DO $$ BEGIN
 ASSERT EXISTS (SELECT 1 FROM costing_retention.fn_purge_run_blockers(87) WHERE blocker='CROSS_RUN_REFERENCE'),'cross-run reference detected';
 PERFORM t.fails('SELECT costing_retention.purge_run_step(87)','CROSS_RUN_REFERENCE');
END $$;
ALTER TABLE costing.cost_sheet_line_traceability_snapshot DISABLE TRIGGER USER;
DELETE FROM costing.cost_sheet_line_traceability_snapshot WHERE refresh_run_id=148 AND parent_evidence_id IN (SELECT id FROM costing.marketing_signed_billed_sales_evidence_snapshot WHERE refresh_run_id=87);
ALTER TABLE costing.cost_sheet_line_traceability_snapshot ENABLE TRIGGER USER;
DO $$ BEGIN ASSERT NOT EXISTS (SELECT 1 FROM costing_retention.fn_purge_run_blockers(87)),'cleared after removing the planted reference'; END $$;
-- 6. schema drift: a newly added run-linked relation, a cascading FK, a permanent->purgeable FK all fail closed
CREATE TABLE costing.drift_new_snapshot(id bigint PRIMARY KEY,refresh_run_id bigint REFERENCES costing.costing_refresh_run(id));
DO $$ BEGIN ASSERT EXISTS (SELECT 1 FROM costing_retention.fn_purge_structural_blockers() WHERE blocker='UNCLASSIFIED_RUN_LINKED_RELATION' AND detail='costing.drift_new_snapshot'),'new relation blocks';
 PERFORM t.fails('SELECT costing_retention.purge_run_step(87)','PURGE_BLOCKED.*UNCLASSIFIED'); END $$;
DROP TABLE costing.drift_new_snapshot;
CREATE TABLE costing.drift_perm(id bigint,ev bigint REFERENCES costing.marketing_signed_billed_sales_evidence_snapshot(id));
DO $$ BEGIN ASSERT EXISTS (SELECT 1 FROM costing_retention.fn_purge_structural_blockers() WHERE blocker='NON_PURGEABLE_REFERENCES_PURGEABLE'),'permanent->purgeable FK blocks'; END $$;
DROP TABLE costing.drift_perm;
CREATE TABLE costing.drift_casc(id bigint,ev bigint REFERENCES costing.marketing_signed_billed_sales_evidence_snapshot(id) ON DELETE CASCADE);
DO $$ BEGIN ASSERT EXISTS (SELECT 1 FROM costing_retention.fn_purge_structural_blockers() WHERE blocker='CASCADING_FK_ON_PURGEABLE'),'cascading FK blocks'; END $$;
DROP TABLE costing.drift_casc;
DO $$ BEGIN ASSERT (SELECT count(*) FROM costing_retention.fn_purge_structural_blockers())=0,'clean again'; END $$;
-- 7. rollback leaves everything untouched
CREATE TABLE t.before AS SELECT refresh_run_id,count(*) n FROM costing.marketing_signed_billed_sales_evidence_snapshot GROUP BY 1;
BEGIN;
SELECT costing_retention.purge_run_step(87,2) \gset
ROLLBACK;
DO $$ BEGIN
 ASSERT (SELECT count(*) FROM costing.marketing_signed_billed_sales_evidence_snapshot WHERE refresh_run_id=87)=5 AND (SELECT count(*) FROM costing.cost_sheet_line_traceability_snapshot WHERE refresh_run_id=87)=5,'rollback restored rows';
 ASSERT (SELECT detail_state FROM costing.costing_run_retention_ledger WHERE refresh_run_id=87)='DETAILS_AVAILABLE','rollback restored ledger state (87 was verified AVAILABLE in 05)';
 ASSERT (SELECT count(*) FROM costing_retention.purge_step_receipt)=0,'rollback left no receipt';
 ASSERT NOT EXISTS (SELECT 1 FROM costing_retention.purge_context),'no leaked authority context';
END $$;
-- 8. silent-skip guard cannot fake a purge: rows exist, delete returns 0 -> fail closed, state rolled back
CREATE FUNCTION t.skip_delete() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NULL; END $$;
CREATE TRIGGER a_silent_skip BEFORE DELETE ON costing.sku_scheme_viability_snapshot FOR EACH ROW EXECUTE FUNCTION t.skip_delete();
DO $o$ BEGIN PERFORM t.fails($q$DO $x$ BEGIN FOR i IN 1..20 LOOP PERFORM costing_retention.purge_run_step(148,1000); END LOOP; END $x$$q$,'PURGE_NO_PROGRESS');
 ASSERT (SELECT detail_state FROM costing.costing_run_retention_ledger WHERE refresh_run_id=148)='DETAILS_UNVERIFIED','state unchanged after failed step'; END $o$;
DROP TRIGGER a_silent_skip ON costing.sku_scheme_viability_snapshot;
-- 9. FAILED run: purge allowed by the same state machine (INCOMPLETE -> PURGED); governance and header untouched
CREATE TABLE t.gov_before AS SELECT (SELECT count(*) FROM costing.costing_run_designation) des,(SELECT count(*) FROM costing.governance_evidence_event) ev,
  (SELECT count(*) FROM costing.regional_marketing_evidence_acceptance) rg,(SELECT count(*) FROM costing.sales_allocation_quantity_driver_acceptance) sl,
  (SELECT count(*) FROM costing.costing_refresh_run) runs,(SELECT count(*) FROM costing.costing_run_retention_ledger) led;
DO $$ DECLARE j jsonb; steps int:=0; BEGIN
 LOOP j:=costing_retention.purge_run_step(149,1000); steps:=steps+1; EXIT WHEN (j->>'done')::boolean; ASSERT steps<50,'loop guard'; END LOOP;
 ASSERT (SELECT detail_state FROM costing.costing_run_retention_ledger WHERE refresh_run_id=149)='DETAILS_PURGED','failed run purged';
END $$;
-- 10. full purge of undesignated September draft 87 with exact accounting
DO $$ DECLARE j jsonb; steps int:=0; exp jsonb; BEGIN
 exp:=jsonb_build_object('marketing_signed_billed_sales_evidence_snapshot',5,'cost_sheet_line_traceability_snapshot',5,'cost_sheet_line_monthly_snapshot',5,'sku_scheme_viability_snapshot',5,
   'sku_sales_allocation_basis_snapshot',3,'sku_regional_marketing_allocation_basis_snapshot',6,'sku_regional_marketing_expense_allocation_snapshot',6);
 LOOP j:=costing_retention.purge_run_step(87,2); steps:=steps+1; EXIT WHEN (j->>'done')::boolean; ASSERT steps<100,'loop guard'; END LOOP;
 ASSERT j->'removed'=exp,'removed counts exact: '||(j->>'removed');
 ASSERT (SELECT (detail_state,removed_row_counts)=('DETAILS_PURGED'::text,exp) FROM costing.costing_run_retention_ledger WHERE refresh_run_id=87),'ledger holds counts';
 ASSERT (SELECT purge_receipt_id IS NOT NULL AND length(verification_digest)=64 AND details_purged_at IS NOT NULL FROM costing.costing_run_retention_ledger WHERE refresh_run_id=87),'receipt+digest';
 ASSERT (SELECT sum(deleted_rows) FROM costing_retention.purge_step_receipt WHERE refresh_run_id=87 AND kind='STEP')=35,'step receipts sum';
 ASSERT (SELECT count(*) FROM costing_retention.purge_step_receipt WHERE refresh_run_id=87 AND kind='FINAL' AND residual_after=0)=1,'final receipt';
 ASSERT (costing_retention.purge_run_step(87)->>'already_purged')::boolean,'idempotent';
 -- residual zero and every other run untouched
 ASSERT (SELECT count(*) FROM costing.marketing_signed_billed_sales_evidence_snapshot WHERE refresh_run_id=87)=0,'no residual';
 ASSERT NOT EXISTS (SELECT 1 FROM t.before b JOIN (SELECT refresh_run_id,count(*) n FROM costing.marketing_signed_billed_sales_evidence_snapshot GROUP BY 1) c USING(refresh_run_id) WHERE b.refresh_run_id NOT IN (87,149) AND b.n<>c.n),'other runs intact';
 ASSERT (SELECT count(*) FROM costing.marketing_signed_billed_sales_evidence_snapshot WHERE refresh_run_id IN (122,143,152,153))=20,'approved and November detail intact';
 ASSERT (SELECT (des,ev,rg,sl,runs,led)=((SELECT count(*) FROM costing.costing_run_designation),(SELECT count(*) FROM costing.governance_evidence_event),(SELECT count(*) FROM costing.regional_marketing_evidence_acceptance),(SELECT count(*) FROM costing.sales_allocation_quantity_driver_acceptance),(SELECT count(*) FROM costing.costing_refresh_run),(SELECT count(*) FROM costing.costing_run_retention_ledger)) FROM t.gov_before),'governance/run header/ledger counts unchanged';
 PERFORM t.fails('SELECT costing_retention.purge_run_step(143)','PURGE_BLOCKED');
 PERFORM t.fails('SELECT costing_retention.purge_run_step(153)','PURGE_BLOCKED');
END $$;
