DO $$ BEGIN ASSERT (SELECT state FROM costing_retention.fn_run_detail_availability(87))='DETAILS_PURGED','R3 sees purged state';
 PERFORM t.fails('SELECT costing.fn_assert_run_details_available(87)','RUN_DETAILS_UNAVAILABLE'); END $$;
